content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_raptor_open",
 "name": "Raptor News: the intro",
 "set": "set_raptor_news",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Anchor"
  },
  "b": {
   "mark": "b",
   "label": "Co-anchor"
  }
 },
 "wallText": "RAPTOR NEWS",
 "wallSub": "{headline}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "jib",
    "frame": "wide",
    "on": [],
    "move": "crane",
    "cut": "dissolve"
   },
   "hold": 3,
   "gfx": [
    {
     "kind": "full",
     "title": "RAPTOR NEWS",
     "sub": "Nightly Fury",
     "at": 0,
     "for": 2.6
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam2",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Good evening, Coldwater. I'm {a.name}, and tonight's top story should frighten you: {headline}.",
     "I'm {a.name}. Sit down. Tonight: {headline}. It's worse than it sounds.",
     "{a.name} here. We lead with this: {headline}. We'll tell you who to blame."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{a.name}",
     "sub": "Raptor News",
     "at": 0.4,
     "for": 4.5
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "And I'm {b.name}. Also coming up, the rest of the bad news.",
     "I'm {b.name}. Don't go anywhere. It isn't safe out there."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{b.name}",
     "sub": "Raptor News",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "table",
     "title": "Tonight",
     "list": "stories",
     "row": "{headline}",
     "limit": 4,
     "side": "right",
     "at": 0.6,
     "for": 0
    }
   ]
  }
 ]
}
